import{_ as a,o,c as t,ag as r}from"./chunks/framework.8tqBsFWt.js";const u=JSON.parse('{"title":"OOO coordination for the week ahead","description":"","frontmatter":{},"headers":[],"relativePath":"playbook/ooo-coordination.md","filePath":"playbook/ooo-coordination.md"}'),n={name:"playbook/ooo-coordination.md"};function i(s,e,l,h,d,p){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="ooo-coordination-for-the-week-ahead" tabindex="-1">OOO coordination for the week ahead <a class="header-anchor" href="#ooo-coordination-for-the-week-ahead" aria-label="Permalink to &quot;OOO coordination for the week ahead&quot;">​</a></h1><p><strong>Cadence</strong>: Weekly (Friday or Monday) · <strong>Who</strong>: Managers and Owners</p><h2 id="situation" tabindex="-1">Situation <a class="header-anchor" href="#situation" aria-label="Permalink to &quot;Situation&quot;">​</a></h2><p>You want to know who&#39;s out next week, on which days, and whether any of those absences need covering. Pending PTO requests waiting on approval also surface here — easy to miss otherwise.</p><h2 id="example-phrasings" tabindex="-1">Example phrasings <a class="header-anchor" href="#example-phrasings" aria-label="Permalink to &quot;Example phrasings&quot;">​</a></h2><ul><li>&quot;who&#39;s off next week&quot;</li><li>&quot;team ooo this week&quot;</li><li>&quot;time off coming up&quot;</li></ul><h2 id="what-vera-returns" tabindex="-1">What VERA returns <a class="header-anchor" href="#what-vera-returns" aria-label="Permalink to &quot;What VERA returns&quot;">​</a></h2><p>A table:</p><p>| Name | Dates out | Type | Approval status |</p><p>Where type is PTO, sick, or leave. Approval status is approved, pending, or rejected.</p><p>Plus:</p><ul><li>Any pending PTO requests flagged for your attention</li><li>For each out person, a note of any projects where they&#39;re the assigned PM or have significant active allocations — the accounts that need cover</li></ul><p>Sorted: pending approvals first, then by start date.</p><h2 id="who-can-run-it" tabindex="-1">Who can run it <a class="header-anchor" href="#who-can-run-it" aria-label="Permalink to &quot;Who can run it&quot;">​</a></h2><p>Managers and Owners. Both see their team&#39;s upcoming absences. Owners can also approve; Managers approve on their own team.</p><h2 id="related-plays" tabindex="-1">Related plays <a class="header-anchor" href="#related-plays" aria-label="Permalink to &quot;Related plays&quot;">​</a></h2><ul><li><a href="./team-availability.html">Team availability for the next two weeks</a> — capacity view once OOO is accounted for</li><li><a href="./my-week-at-a-glance.html">My week at a glance</a> — the team member&#39;s own view of their time off</li></ul>',17)])])}const f=a(n,[["render",i]]);export{u as __pageData,f as default};
